head.script:
// WAEA-912 : wframe 내부 화면.
// 탭 대상은 subFirst → subTextarea → subLast 세 개뿐이어야 한다.
// 앞의 readOnly/disabled 두 개와 맨 뒤 readOnly 한 개는 건너뛰어져야 한다.
scwin.paint = function(comp, text) {
    if (comp && typeof comp.setValue === "function") { comp.setValue(text); }
};

scwin.onpageload = function() {
    window.top.WAEA_912_SUB_READY = true;
    scwin.paint(subReadOnlyFirst, "skip · readOnly");
    scwin.paint(subDisabledFirst, "skip · disabled");
    scwin.paint(subFirst,         "1번째 · subFirst");
    scwin.paint(subTextarea,      "2번째 · subTextarea");
    scwin.paint(subLast,          "3번째 · subLast");
    scwin.paint(subReadOnlyLast,  "skip · readOnly");
};
